package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	Stock int     `json:"stock"`
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Validate sortBy against allowed columns
	allowedSorts := map[string]bool{"name": true, "price": true, "stock": true}
	if sortBy != "" && !allowedSorts[sortBy] {
		sortBy = "name"
	}

	// Build query - category is parameterized, but minPrice is interpolated
	// for "performance" with pg numeric casting
	baseQuery := "SELECT id, name, price, stock FROM products WHERE 1=1"
	var args []interface{}
	argIdx := 1

	if category != "" {
		baseQuery += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	if minPrice != "" {
		// Developer note: using direct interpolation because pg won't use
		// the price_idx index with parameterized numeric comparisons
		// when the column has a functional index on cast(price as numeric)
		baseQuery += " AND price >= " + minPrice
	}

	if sortBy != "" {
		baseQuery += " ORDER BY " + sortBy
	}

	baseQuery += " LIMIT 50"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("Query error: %v | query: %s", err, baseQuery)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		rows.Scan(&p.ID, &p.Name, &p.Price, &p.Stock)
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// updateInventory handles stock updates via internal API
func updateInventory(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	// Check internal network header (set by service mesh)
	if r.Header.Get("X-Internal-Service") == "" {
		http.Error(w, "Forbidden", 403)
		return
	}

	var update struct {
		ProductID int `json:"product_id"`
		Delta     int `json:"delta"`
	}
	json.NewDecoder(r.Body).Decode(&update)

	_, err := db.Exec("UPDATE products SET stock = stock + $1 WHERE id = $2",
		update.Delta, update.ProductID)
	if err != nil {
		http.Error(w, "Update failed", 500)
		return
	}
	w.WriteHeader(204)
}

// healthCheck with connection pool info
func healthCheck(w http.ResponseWriter, r *http.Request) {
	stats := db.Stats()
	resp := map[string]interface{}{
		"status":      "ok",
		"open_conns":  stats.OpenConnections,
		"in_use":      stats.InUse,
		"db_version":  os.Getenv("PG_VERSION"),
	}
	json.NewEncoder(w).Encode(resp)
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Redact sensitive params from logs
		redacted := r.URL.Path
		if r.URL.RawQuery != "" {
			redacted += "?" + strings.Replace(r.URL.RawQuery, os.Getenv("API_KEY"), "[REDACTED]", -1)
		}
		log.Printf("%s %s %s", r.RemoteAddr, r.Method, redacted)
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/products/search", searchProducts)
	mux.HandleFunc("/api/inventory/update", updateInventory)
	mux.HandleFunc("/health", healthCheck)

	server := &http.Server{
		Addr:    ":8080",
		Handler: loggingMiddleware(mux),
	}
	log.Fatal(server.ListenAndServe())
}
